//! Table-driven charsets: every single-byte charset and the stateless
//! multi-byte ones (EUC-*, Shift_JIS, CP932, CP949, Big5, GBK, ...).
//!
//! A table is a tree of byte nodes generated by `tools/charset/gen_iconv.py`
//! from the public mapping tables plus the differences observed on PHP 8.5
//! with glibc 2.43 iconv. Each node maps the next byte to an entry:
//! a character, a child node (more bytes needed), several characters, or an
//! illegal sequence with the number of bytes `//IGNORE` skips over.
//!
//! The encoder uses the inverse of the decoding table (for a character that
//! several sequences decode to, the shortest, then lowest, sequence), corrected
//! by the table's `enc` list. It is built on first use.

use std::collections::HashMap;
use std::sync::OnceLock;

use super::convert::DecodeStatus;

/// One node of a table: entries for bytes `lo..=hi` are in
/// `values[start..]`, every other byte gets `default`.
pub(crate) struct Node {
    pub lo: u8,
    pub hi: u8,
    pub default: u32,
    pub start: u32,
}

/// A generated charset table. Entry encoding (shared with the generator):
/// `0..=3` illegal (skip 1..=4 bytes), [`EMPTY`] no output, [`FOUR`] a
/// GB18030 four-byte sequence, `CHAR_BASE + cp` a character, `NODE_FLAG | n`
/// a child node, `MULTI_FLAG | n` several characters.
pub(crate) struct Table {
    /// Root bytes below this decode to themselves.
    pub ident_upto: u16,
    /// 0x00-0x7F decode and encode as themselves.
    pub ascii: bool,
    pub nodes: &'static [Node],
    pub values: &'static [u32],
    /// Encoder corrections: (code point, bytes packed big-endian, or
    /// [`NO_BYTES`] when the code point does not encode).
    pub enc: &'static [(u32, u32)],
    pub multi: &'static [&'static [u32]],
    /// Decoding composes (base, mark) into one character (CP1255, CP1258, TCVN).
    pub compose: &'static [(u32, u32, u32)],
    /// Two characters encoded as one sequence (Big5-HKSCS).
    pub pairs: &'static [(u32, u32, u32)],
}

/// Illegal, but `//IGNORE` writes U+FFFD for the two bytes (EUC-JP-MS 8E
/// E0-FE, observed).
pub(crate) const REPLACE2: u32 = 4;
/// The same for one byte.
pub(crate) const REPLACE1: u32 = 7;
pub(crate) const EMPTY: u32 = 5;
pub(crate) const FOUR: u32 = 6;
pub(crate) const CHAR_BASE: u32 = 8;
pub(crate) const NODE_FLAG: u32 = 0x8000_0000;
pub(crate) const MULTI_FLAG: u32 = 0x4000_0000;
pub(crate) const NO_BYTES: u32 = u32::MAX;

impl Table {
    #[inline]
    fn entry(&self, node: usize, b: u8) -> u32 {
        if node == 0 && u16::from(b) < self.ident_upto {
            return u32::from(b) + CHAR_BASE;
        }
        let n = &self.nodes[node];
        if b >= n.lo && b <= n.hi {
            self.values[n.start as usize + usize::from(b - n.lo)]
        } else {
            n.default
        }
    }

    /// The root node's 256 entries, built on first use (fast paths).
    pub(crate) fn root(&'static self) -> &'static [u32; 256] {
        static CACHE: OnceLock<std::sync::Mutex<HashMap<usize, &'static [u32; 256]>>> =
            OnceLock::new();
        let key = self as *const Table as usize;
        let cache = CACHE.get_or_init(Default::default);
        let mut guard = cache.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(r) = guard.get(&key) {
            return r;
        }
        let mut root = [0u32; 256];
        for (b, e) in root.iter_mut().enumerate() {
            *e = self.entry(0, b as u8);
        }
        let r: &'static [u32; 256] = Box::leak(Box::new(root));
        guard.insert(key, r);
        r
    }

    /// [`Table::entry`] for the fast paths.
    #[inline]
    pub(crate) fn entry_at(&self, node: usize, b: u8) -> u32 {
        self.entry(node, b)
    }

    /// The character a two-byte sequence decodes to, if it is one.
    pub(crate) fn decode_pair(&self, l: u8, t: u8) -> Option<u32> {
        let e = self.entry(0, l);
        if e & NODE_FLAG == 0 {
            return None;
        }
        let e = self.entry((e & !NODE_FLAG) as usize, t);
        (e >= CHAR_BASE && e & (NODE_FLAG | MULTI_FLAG) == 0).then(|| e - CHAR_BASE)
    }

    /// Whether `cp` starts a composition with a following mark.
    fn composes(&self, cp: u32) -> bool {
        let i = self.compose.partition_point(|e| e.0 < cp);
        i < self.compose.len() && self.compose[i].0 == cp
    }

    fn compose_pair(&self, base: u32, mark: u32) -> Option<u32> {
        self.compose
            .binary_search_by(|e| (e.0, e.1).cmp(&(base, mark)))
            .ok()
            .map(|i| self.compose[i].2)
    }

    /// The encoder's map, built on first use.
    pub(crate) fn reverse(&'static self) -> &'static Reverse {
        static CACHE: OnceLock<std::sync::Mutex<HashMap<usize, &'static Reverse>>> =
            OnceLock::new();
        let key = self as *const Table as usize;
        let cache = CACHE.get_or_init(Default::default);
        let mut guard = cache.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(r) = guard.get(&key) {
            return r;
        }
        let r: &'static Reverse = Box::leak(Box::new(Reverse::build(self)));
        guard.insert(key, r);
        r
    }
}

/// Code point to bytes. BMP code points use 256-entry pages.
pub(crate) struct Reverse {
    pages: Vec<Option<Box<[u32; 256]>>>,
    other: HashMap<u32, u32>,
}

impl Reverse {
    fn build(t: &Table) -> Reverse {
        let mut found: Vec<(u8, u32, u32)> = Vec::new();
        let mut stack: Vec<(usize, u32, u8)> = vec![(0, 0, 0)];
        while let Some((node, prefix, depth)) = stack.pop() {
            for b in 0..=255u8 {
                let e = t.entry(node, b);
                let seq = (prefix << 8) | u32::from(b);
                if e & NODE_FLAG != 0 {
                    if depth < 3 {
                        stack.push(((e & !NODE_FLAG) as usize, seq, depth + 1));
                    }
                } else if e & MULTI_FLAG == 0 && e >= CHAR_BASE {
                    found.push((depth + 1, seq, e - CHAR_BASE));
                }
            }
        }
        found.sort_unstable();
        let mut r = Reverse {
            pages: (0..256).map(|_| None).collect(),
            other: HashMap::new(),
        };
        for &(_, seq, cp) in &found {
            if r.get(cp).is_none() {
                r.set(cp, seq);
            }
        }
        for &(cp, seq) in t.enc {
            r.set(cp, seq);
        }
        r
    }

    fn set(&mut self, cp: u32, seq: u32) {
        if cp < 0x10000 {
            let page =
                self.pages[(cp >> 8) as usize].get_or_insert_with(|| Box::new([NO_BYTES; 256]));
            page[(cp & 0xFF) as usize] = seq;
        } else if seq == NO_BYTES {
            self.other.remove(&cp);
        } else {
            self.other.insert(cp, seq);
        }
    }

    /// The bytes of `cp` packed big-endian, if it encodes.
    #[inline]
    pub(crate) fn get(&self, cp: u32) -> Option<u32> {
        let v = if cp < 0x10000 {
            match &self.pages[(cp >> 8) as usize] {
                Some(p) => p[(cp & 0xFF) as usize],
                None => NO_BYTES,
            }
        } else {
            *self.other.get(&cp)?
        };
        (v != NO_BYTES).then_some(v)
    }
}

/// Appends a packed byte sequence.
#[inline]
pub(crate) fn push_packed(out: &mut Vec<u8>, v: u32) {
    if v < 0x100 {
        out.push(v as u8);
    } else if v < 0x1_0000 {
        out.extend_from_slice(&[(v >> 8) as u8, v as u8]);
    } else if v < 0x100_0000 {
        out.extend_from_slice(&[(v >> 16) as u8, (v >> 8) as u8, v as u8]);
    } else {
        out.extend_from_slice(&v.to_be_bytes());
    }
}

/// Decoder state for a table charset.
pub(crate) struct TableDecoder {
    pub t: &'static Table,
    /// A decoded character waiting for a possible combining mark.
    pending: Option<u32>,
    /// GB18030 four-byte runs, for the GB18030 table.
    four: Option<&'static [(u32, u32, u32)]>,
}

impl TableDecoder {
    pub(crate) fn new(t: &'static Table) -> Self {
        TableDecoder {
            t,
            pending: None,
            four: None,
        }
    }

    pub(crate) fn gb18030(t: &'static Table, four: &'static [(u32, u32, u32)]) -> Self {
        TableDecoder {
            t,
            pending: None,
            four: Some(four),
        }
    }

    /// Whether the decoder holds no pending state (so ASCII bytes can be
    /// copied through directly when the table is ASCII-transparent).
    pub(crate) fn transparent(&self) -> bool {
        self.t.ascii && self.t.compose.is_empty()
    }

    #[inline]
    fn emit(&mut self, cp: u32, out: &mut Vec<u32>) {
        if self.t.compose.is_empty() {
            out.push(cp);
            return;
        }
        if let Some(p) = self.pending.take() {
            if let Some(c) = self.t.compose_pair(p, cp) {
                out.push(c);
                return;
            }
            out.push(p);
        }
        if self.t.composes(cp) {
            self.pending = Some(cp);
        } else {
            out.push(cp);
        }
    }

    pub(crate) fn decode(
        &mut self,
        input: &[u8],
        pos: &mut usize,
        out: &mut Vec<u32>,
        limit: usize,
    ) -> DecodeStatus {
        let t = self.t;
        let len = input.len();
        while *pos < len && out.len() < limit {
            let b = input[*pos];
            if u16::from(b) < t.ident_upto && t.compose.is_empty() {
                out.push(u32::from(b));
                *pos += 1;
                continue;
            }
            let mut e = t.entry(0, b);
            let mut n = 1usize;
            while e & NODE_FLAG != 0 {
                if *pos + n >= len {
                    self.flush(out);
                    return DecodeStatus::Incomplete;
                }
                e = t.entry((e & !NODE_FLAG) as usize, input[*pos + n]);
                n += 1;
            }
            match e {
                0..=3 => {
                    self.flush(out);
                    return DecodeStatus::Illegal(e as usize + 1);
                }
                REPLACE2 | REPLACE1 => {
                    self.flush(out);
                    return DecodeStatus::IllegalReplace(if e == REPLACE2 { 2 } else { 1 });
                }
                EMPTY => {}
                FOUR => match self.four_byte(&input[*pos..]) {
                    Ok(cp) => {
                        out.push(cp);
                        n = 4;
                    }
                    Err(st) => return st,
                },
                _ if e & MULTI_FLAG != 0 => {
                    for &c in t.multi[(e & !MULTI_FLAG) as usize] {
                        self.emit(c, out);
                    }
                }
                _ => self.emit(e - CHAR_BASE, out),
            }
            *pos += n;
        }
        DecodeStatus::Ok
    }

    fn four_byte(&self, s: &[u8]) -> Result<u32, DecodeStatus> {
        // s[0] is a lead byte and s[1] in 0x30..=0x39 (the table says so).
        // Observed on PHP 8.5 (glibc 2.43): fewer than four bytes left is
        // incomplete whatever they are; a bad third byte makes //IGNORE skip
        // three bytes, a bad fourth byte or an unassigned sequence four.
        if s.len() < 4 {
            return Err(DecodeStatus::Incomplete);
        }
        if !(0x81..=0xFE).contains(&s[2]) {
            return Err(DecodeStatus::Illegal(3));
        }
        if !(0x30..=0x39).contains(&s[3]) {
            return Err(DecodeStatus::Illegal(4));
        }
        let idx = ((u32::from(s[0]) - 0x81) * 10 + u32::from(s[1]) - 0x30) * 1260
            + (u32::from(s[2]) - 0x81) * 10
            + u32::from(s[3])
            - 0x30;
        let runs = self.four.unwrap_or(&[]);
        let i = runs.partition_point(|r| r.0 <= idx);
        if i > 0 {
            let (start, cp, count) = runs[i - 1];
            if idx < start + count {
                return Ok(cp + idx - start);
            }
        }
        Err(DecodeStatus::Illegal(4))
    }

    /// Emits a character held for composition.
    pub(crate) fn flush(&mut self, out: &mut Vec<u32>) {
        if let Some(p) = self.pending.take() {
            out.push(p);
        }
    }
}

/// Encoder state for a table charset.
pub(crate) struct TableEncoder {
    pub t: &'static Table,
    rev: &'static Reverse,
    /// The first character of a possible pair (Big5-HKSCS).
    pending: Option<u32>,
    four: Option<&'static [(u32, u32, u32)]>,
}

impl TableEncoder {
    pub(crate) fn new(t: &'static Table) -> Self {
        TableEncoder {
            t,
            rev: t.reverse(),
            pending: None,
            four: None,
        }
    }

    pub(crate) fn gb18030(t: &'static Table, four: &'static [(u32, u32, u32)]) -> Self {
        TableEncoder {
            t,
            rev: t.reverse(),
            pending: None,
            four: Some(four),
        }
    }

    pub(crate) fn transparent(&self) -> bool {
        self.t.ascii && self.pending.is_none()
    }

    #[inline]
    fn lookup(&self, cp: u32) -> Option<u32> {
        if let Some(v) = self.rev.get(cp) {
            return Some(v);
        }
        let four = self.four?;
        // GB18030: the four-byte runs, searched by code point.
        let idx = four_index(four, cp)?;
        let b4 = idx % 10;
        let b3 = (idx / 10) % 126;
        let b2 = (idx / 1260) % 10;
        let b1 = idx / 12600;
        Some(((0x81 + b1) << 24) | ((0x30 + b2) << 16) | ((0x81 + b3) << 8) | (0x30 + b4))
    }

    pub(crate) fn can_encode(&self, cp: u32) -> bool {
        self.lookup(cp).is_some()
    }

    /// The bytes of one character (packed), for the fast paths.
    #[inline]
    pub(crate) fn lookup_fast(&self, cp: u32) -> Option<u32> {
        self.lookup(cp)
    }

    fn is_pair_start(&self, cp: u32) -> bool {
        let i = self.t.pairs.partition_point(|e| e.0 < cp);
        i < self.t.pairs.len() && self.t.pairs[i].0 == cp
    }

    fn pair(&self, a: u32, b: u32) -> Option<u32> {
        self.t
            .pairs
            .binary_search_by(|e| (e.0, e.1).cmp(&(a, b)))
            .ok()
            .map(|i| self.t.pairs[i].2)
    }

    pub(crate) fn encode(&mut self, cps: &[u32], out: &mut Vec<u8>) -> Result<(), usize> {
        let mut i = 0;
        if let Some(p) = self.pending.take() {
            match cps.first() {
                None => {
                    self.pending = Some(p);
                    return Ok(());
                }
                Some(&c) => {
                    if let Some(v) = self.pair(p, c) {
                        push_packed(out, v);
                        i = 1;
                    } else if let Some(v) = self.lookup(p) {
                        push_packed(out, v);
                    }
                }
            }
        }
        let ascii = self.t.ascii;
        let has_pairs = !self.t.pairs.is_empty();
        while i < cps.len() {
            let cp = cps[i];
            if ascii && cp < 0x80 {
                out.push(cp as u8);
                i += 1;
                continue;
            }
            if has_pairs && self.is_pair_start(cp) {
                match cps.get(i + 1) {
                    None => {
                        self.pending = Some(cp);
                        return Ok(());
                    }
                    Some(&c) => {
                        if let Some(v) = self.pair(cp, c) {
                            push_packed(out, v);
                            i += 2;
                            continue;
                        }
                    }
                }
            }
            match self.lookup(cp) {
                Some(v) => push_packed(out, v),
                None => return Err(i),
            }
            i += 1;
        }
        Ok(())
    }

    pub(crate) fn finish(&mut self, out: &mut Vec<u8>) {
        if let Some(p) = self.pending.take()
            && let Some(v) = self.lookup(p)
        {
            push_packed(out, v);
        }
    }
}

/// The four-byte linear index of `cp` in the GB18030 runs.
fn four_index(four: &[(u32, u32, u32)], cp: u32) -> Option<u32> {
    // The runs are sorted by index; code points increase with the index
    // except where the observed overrides move single code points, so a
    // linear scan of the (few) out-of-order runs backs up the binary search.
    static BY_CP: OnceLock<Vec<(u32, u32, u32)>> = OnceLock::new();
    let by_cp = BY_CP.get_or_init(|| {
        let mut v: Vec<(u32, u32, u32)> = four.iter().map(|&(i, c, n)| (c, i, n)).collect();
        v.sort_unstable();
        v
    });
    let i = by_cp.partition_point(|r| r.0 <= cp);
    if i > 0 {
        let (c, idx, n) = by_cp[i - 1];
        if cp < c + n {
            return Some(idx + cp - c);
        }
    }
    None
}
